import { Controller, Post, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 문서번호는 'DOC-날짜-난수9자리'로 자동 채번한다 (채번 방식은 확정 전).
// 가정: 기안 시 submitted_at은 현재 시각(now())으로 채운다.

type Db = {
  query: (sql: string, params?: Record<string, unknown>) => Promise<any[]>;
};

const MAX_TITLE_LENGTH = 500;

const DOCUMENT_NO_SQL =
  "'DOC-' || to_char(now(), 'YYYYMMDD') || '-' || lpad(CAST(CAST(floor(random() * 1000000000) AS bigint) AS text), 9, '0')";

function isBlank(value: unknown): boolean {
  return value === undefined || value === null || (typeof value === 'string' && value.trim() === '');
}

async function draftProblem(db: Db, item: unknown): Promise<string | null> {
  if (item === null || typeof item !== 'object' || Array.isArray(item)) {
    return '문서 정보가 없습니다.';
  }
  const doc = item as Record<string, unknown>;
  if (isBlank(doc['approvalFormId']) || !Number.isInteger(Number(doc['approvalFormId']))) {
    return '결재양식을 선택해야 합니다.';
  }
  if (typeof doc['title'] !== 'string' || doc['title'].trim() === '') {
    return '문서 제목을 입력해야 합니다.';
  }
  if (doc['title'].length > MAX_TITLE_LENGTH) {
    return '문서 제목은 500자 이하여야 합니다.';
  }
  if (doc['body'] !== undefined && doc['body'] !== null && typeof doc['body'] !== 'string') {
    return '문서 본문 형식이 올바르지 않습니다.';
  }
  const forms = await db.query(
    'SELECT use_status AS "useStatus" FROM approval_form WHERE approval_form_id = CAST(:formId AS bigint)',
    { formId: String(doc['approvalFormId']) },
  );
  if (forms.length === 0 || forms[0].useStatus !== '사용') {
    return '사용 중인 결재양식을 선택해야 합니다.';
  }
  return null;
}

async function insertDraft(
  db: Db,
  userId: string,
  formId: string,
  title: string,
  body: string | null,
  status: string,
): Promise<{ approvalDocumentId: number; documentNo: string; approvalStatus: string }> {
  const rows = await db.query(
    'INSERT INTO approval_document (document_no, approval_form_id, drafter_id, title, body, approval_status, submitted_at, created_at, updated_at) ' +
      'VALUES (' + DOCUMENT_NO_SQL + ', CAST(:formId AS bigint), CAST(:userId AS bigint), :title, CAST(:body AS text), :status, now(), now(), now()) ' +
      'RETURNING approval_document_id AS "approvalDocumentId", document_no AS "documentNo", approval_status AS "approvalStatus"',
    { formId, userId, title, body, status },
  );
  return rows[0];
}

@Controller('api/v1')
export class FnSfr02904Controller {
  @Post('/approval-documents')
  @HttpCode(200)
  async createApprovalDocument(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const data = checks.inputOf(req.body);
    return transaction(async (db) => {
      const problem = await draftProblem(db, data);
      if (problem !== null) {
        throw new ApiError(422, 'REQUIRED_FIELD_MISSING', problem);
      }
      const body = typeof data['body'] === 'string' ? data['body'] : null;
      return insertDraft(db, user.id, String(data['approvalFormId']), String(data['title']), body, '기안');
    });
  }

  @Post('/approval-documents/batch-draft')
  @HttpCode(200)
  async batchDraftApprovalDocuments(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const data = checks.inputOf(req.body);
    return transaction(async (db) => {
      const documents = data['documents'];
      if (!Array.isArray(documents) || documents.length === 0) {
        throw new ApiError(422, 'REQUIRED_FIELD_MISSING', '일괄 기안할 문서를 선택해야 합니다.');
      }
      // 필수값이 누락된 문서가 하나라도 있으면 사유를 안내하고 아무것도 기안하지 않는다.
      const reasons: string[] = [];
      for (let i = 0; i < documents.length; i += 1) {
        const problem = await draftProblem(db, documents[i]);
        if (problem !== null) {
          reasons.push(`${i + 1}번째 문서: ${problem}`);
        }
      }
      if (reasons.length > 0) {
        throw new ApiError(422, 'REQUIRED_FIELD_MISSING', `기안하지 못한 문서가 있습니다. ${reasons.join(' / ')}`);
      }
      const results: { approvalDocumentId: number; documentNo: string; approvalStatus: string }[] = [];
      for (const item of documents) {
        const doc = item as Record<string, unknown>;
        const body = typeof doc['body'] === 'string' ? doc['body'] : null;
        const row = await insertDraft(db, user.id, String(doc['approvalFormId']), String(doc['title']), body, '기안');
        results.push(row);
      }
      return { draftedCount: results.length, results };
    });
  }

  @Post('/approval-documents/:approvalDocumentId/redraft')
  @HttpCode(200)
  async redraftApprovalDocument(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const approvalDocumentId = req.params['approvalDocumentId'];
    const data = checks.inputOf(req.body);
    return transaction(async (db) => {
      if (!/^[0-9]+$/.test(approvalDocumentId)) {
        throw new ApiError(404, 'APPROVAL_DOCUMENT_NOT_FOUND', '원본 문서를 찾을 수 없습니다.');
      }
      const originals = await db.query(
        'SELECT approval_form_id AS "approvalFormId", body AS "body", approval_status AS "approvalStatus" ' +
          'FROM approval_document WHERE approval_document_id = CAST(:id AS bigint) FOR UPDATE',
        { id: approvalDocumentId },
      );
      if (originals.length === 0) {
        throw new ApiError(404, 'APPROVAL_DOCUMENT_NOT_FOUND', '원본 문서를 찾을 수 없습니다.');
      }
      const original = originals[0];
      if (original.approvalStatus !== '반려' && original.approvalStatus !== '회수') {
        throw new ApiError(409, 'REDRAFT_NOT_ALLOWED', '반려 또는 회수된 문서만 재기안할 수 있습니다.');
      }
      const title = data['title'];
      if (typeof title !== 'string' || title.trim() === '') {
        throw new ApiError(400, 'VALIDATION_FAILED', '문서 제목을 입력해야 합니다.');
      }
      if (title.length > MAX_TITLE_LENGTH) {
        throw new ApiError(400, 'VALIDATION_FAILED', '문서 제목은 500자 이하여야 합니다.');
      }
      if (data['body'] !== undefined && data['body'] !== null && typeof data['body'] !== 'string') {
        throw new ApiError(400, 'VALIDATION_FAILED', '문서 본문 형식이 올바르지 않습니다.');
      }
      // 본문을 보내지 않으면 기작성 문서의 본문을 그대로 불러온다.
      const body = typeof data['body'] === 'string' ? data['body'] : original.body ?? null;
      return insertDraft(db, user.id, String(original.approvalFormId), title, body, '재기안');
    });
  }
}

