import { useState } from 'react';
import {
  call,
  Band,
  Badge,
  DataTable,
  Drawer,
  Field,
  Form,
  LookupSelect,
  TextInput,
  type PageProps,
  type Row,
} from '../kit';

type Mode = 'create' | 'batch' | 'redraft' | null;

interface DraftItem {
  approvalFormId: number | string;
  title: string;
  body: string;
}

const emptyItem = (): DraftItem => ({ approvalFormId: '', title: '', body: '' });

export default function FnSfr02904Page({ role, notify }: PageProps) {
  const [mode, setMode] = useState<Mode>(null);
  const [results, setResults] = useState<Row[]>([]);
  const [form, setForm] = useState<DraftItem>(emptyItem());
  const [items, setItems] = useState<DraftItem[]>([emptyItem()]);
  const [sourceId, setSourceId] = useState<number | string>('');

  const close = () => setMode(null);

  const open = (next: Mode) => {
    setForm(emptyItem());
    setItems([emptyItem()]);
    setSourceId('');
    setMode(next);
  };

  const addResults = (rows: Row[]) => setResults((prev) => [...rows, ...prev]);

  const missing = (item: DraftItem): string | null => {
    if (item.approvalFormId === '') return '결재양식을 선택해야 합니다.';
    if (item.title.trim() === '') return '문서 제목을 입력해야 합니다.';
    return null;
  };

  const submitCreate = async () => {
    const problem = missing(form);
    if (problem) throw new Error(problem);
    const res = await call('POST', '/approval-documents', role, {
      approvalFormId: form.approvalFormId,
      title: form.title,
      body: form.body,
    });
    addResults([{ ...res, title: form.title, kind: '기안' }]);
    notify('문서를 기안했습니다.');
    close();
  };

  const submitBatch = async () => {
    for (let i = 0; i < items.length; i += 1) {
      const problem = missing(items[i]);
      if (problem) throw new Error(`${i + 1}번째 문서: ${problem}`);
    }
    const res = await call<{ draftedCount: number; results: Row[] }>('POST', '/approval-documents/batch-draft', role, {
      documents: items.map((it) => ({ approvalFormId: it.approvalFormId, title: it.title, body: it.body })),
    });
    addResults(
      res.results.map((r, i) => ({ ...r, title: items[i]?.title ?? '', kind: '일괄기안' })).reverse(),
    );
    notify(`${res.draftedCount}건을 일괄 기안했습니다.`);
    close();
  };

  const submitRedraft = async () => {
    if (sourceId === '') throw new Error('재기안할 문서를 선택해야 합니다.');
    if (form.title.trim() === '') throw new Error('문서 제목을 입력해야 합니다.');
    const body: Row = { title: form.title };
    if (form.body.trim() !== '') body.body = form.body;
    const res = await call('POST', `/approval-documents/${sourceId}/redraft`, role, body);
    addResults([{ ...res, title: form.title, kind: '재기안' }]);
    notify('문서를 재기안했습니다.');
    close();
  };

  const changeItem = (index: number, patch: Partial<DraftItem>) => {
    setItems((prev) => prev.map((it, i) => (i === index ? { ...it, ...patch } : it)));
  };

  return (
    <div>
      <h1>일괄기안·재기안</h1>
      <Band total={results.length}>
        <button className="ghost" onClick={() => open('batch')}>일괄 기안</button>
        <button className="ghost" onClick={() => open('redraft')}>재기안</button>
        <button onClick={() => open('create')}>문서 기안</button>
      </Band>
      <DataTable
        rows={results}
        empty="아직 기안한 문서가 없습니다. 문서 기안 버튼으로 첫 문서를 작성해 보세요."
        columns={[
          { key: 'documentNo', label: '문서번호' },
          { key: 'title', label: '문서 제목' },
          { key: 'kind', label: '구분' },
          { key: 'approvalStatus', label: '전자결재 처리 상태', render: (r) => <Badge value={r.approvalStatus} /> },
        ]}
      />

      {mode === 'create' && (
        <Drawer title="문서 기안" onClose={close}>
          <Form onSubmit={submitCreate} submit="기안">
            <Field label="결재양식" required wide>
              <LookupSelect
                table="approval_form"
                role={role}
                value={form.approvalFormId}
                onChange={(v) => setForm({ ...form, approvalFormId: v })}
              />
            </Field>
            <Field label="문서 제목" required wide>
              <TextInput value={form.title} onChange={(v) => setForm({ ...form, title: v })} />
            </Field>
            <Field label="문서 본문" wide>
              <TextInput multiline value={form.body} onChange={(v) => setForm({ ...form, body: v })} />
            </Field>
          </Form>
        </Drawer>
      )}

      {mode === 'batch' && (
        <Drawer title="일괄 기안" onClose={close}>
          <Form
            onSubmit={submitBatch}
            submit="일괄 기안"
            note="선택한 문서는 각각 별도 결재문서로 기안됩니다. 필수값이 빠진 문서가 있으면 어느 문서도 기안되지 않습니다."
          >
            {items.map((it, index) => (
              <div key={index}>
                <h2>{index + 1}번째 문서</h2>
                <Field label="결재양식" required wide>
                  <LookupSelect
                    table="approval_form"
                    role={role}
                    value={it.approvalFormId}
                    onChange={(v) => changeItem(index, { approvalFormId: v })}
                  />
                </Field>
                <Field label="문서 제목" required wide>
                  <TextInput value={it.title} onChange={(v) => changeItem(index, { title: v })} />
                </Field>
                <Field label="문서 본문" wide>
                  <TextInput multiline value={it.body} onChange={(v) => changeItem(index, { body: v })} />
                </Field>
                {items.length > 1 && (
                  <button
                    type="button"
                    className="ghost"
                    onClick={() => setItems((prev) => prev.filter((_, i) => i !== index))}
                  >
                    이 문서 빼기
                  </button>
                )}
              </div>
            ))}
            <button type="button" className="ghost" onClick={() => setItems((prev) => [...prev, emptyItem()])}>
              문서 추가
            </button>
          </Form>
        </Drawer>
      )}

      {mode === 'redraft' && (
        <Drawer title="재기안" onClose={close}>
          <Form
            onSubmit={submitRedraft}
            submit="재기안"
            note="반려되거나 회수된 문서만 재기안할 수 있습니다. 본문을 비워 두면 원본 문서의 본문을 그대로 가져옵니다."
          >
            <Field label="원본 문서" required wide>
              <LookupSelect table="approval_document" role={role} value={sourceId} onChange={setSourceId} />
            </Field>
            <Field label="문서 제목" required wide>
              <TextInput value={form.title} onChange={(v) => setForm({ ...form, title: v })} />
            </Field>
            <Field label="문서 본문" wide>
              <TextInput multiline value={form.body} onChange={(v) => setForm({ ...form, body: v })} />
            </Field>
          </Form>
        </Drawer>
      )}
    </div>
  );
}
